begin;
with j as (select * from jsonb_to_recordset($law7d0013$[{"code_id":"APK_RF","article_number":"25","version_date":"2002-07-24","article_text":"1. В случае заявления отвода арбитражный суд заслушивает мнение лиц, участвующих в деле, а также лица, которому заявлен отвод, если отводимый желает дать объяснения.\n\n2. Вопрос об отводе судьи, рассматривающего дело единолично, разрешается тем же судьей.\n\n3. Вопрос об отводе судьи при рассмотрении дела в коллегиальном составе разрешается этим же составом суда большинством голосов в отсутствие судьи, которому заявлен отвод. При равном числе голосов, поданных за отвод и против отвода, судья считается отведенным.\n\nВопрос об отводе, заявленном нескольким судьям или всему рассматривающему дело составу суда, разрешается всеми судьями, рассматривающими дело, простым большинством голосов.\n\n4. Вопрос об отводе помощника судьи, секретаря судебного заседания, эксперта, специалиста, переводчика разрешается составом суда, рассматривающим дело.\n\n5. По результатам рассмотрения вопроса о самоотводе или об отводе выносится определение.\n\n(Статья в редакции Федерального закона от 28.11.2018 № 451-ФЗ)","article_title":"Статья 25. Порядок разрешения заявленного отвода","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8dbb8fb742e71b9f023f2e9eb2cb064683900e25891c8f41a29926c2d3f9daaa"},{"code_id":"APK_RF","article_number":"250","version_date":"2002-07-24","article_text":"По делам с участием иностранных лиц, отнесенным к компетенции арбитражных судов в Российской Федерации в соответствии с главой 32 настоящего Кодекса, арбитражный суд в Российской Федерации может принять обеспечительные меры по правилам главы 8 настоящего Кодекса.","article_title":"Статья 250. Компетенция арбитражных судов в Российской Федерации по применению обеспечительных мер по делам с участием иностранных лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3f159c0864cb97e4d99984b4a90e1b9ca7c70d2f3b0ff885494c7af5bec10497"},{"code_id":"APK_RF","article_number":"251","version_date":"2002-07-24","article_text":"1. Судебный иммунитет международных организаций определяется международным договором Российской Федерации, федеральным законом.\n\n2. Отказ от судебного иммунитета должен быть произведен в порядке, предусмотренном правилами международной организации. В этом случае арбитражный суд рассматривает дело в порядке, установленном настоящим Кодексом.\n\n(Статья в редакции Федерального закона от 29.12.2015 № 393-ФЗ)","article_title":"Статья 251. Судебный иммунитет международных организаций","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c20ee20849217589f660fa627e15ffd761cbc8c844c62ed53f1796a69671c8b2"},{"code_id":"APK_RF","article_number":"253","version_date":"2002-07-24","article_text":"1. Дела с участием иностранных лиц рассматриваются арбитражным судом по правилам настоящего Кодекса с особенностями, предусмотренными настоящей главой, если международным договором Российской Федерации не предусмотрено иное.\n\n2. Дела с участием иностранных лиц, если эти лица или их органы управления, филиалы, представительства либо их представители, уполномоченные на ведение дела, находятся или проживают на территории Российской Федерации, рассматриваются в сроки, установленные настоящим Кодексом.","article_title":"Статья 253. Порядок рассмотрения дел с участием иностранных лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a7cb927f1ab46aea9390aecfac7b9ccf6911bef5f90de25f7c466c5cfb07e1a1"},{"code_id":"APK_RF","article_number":"254","version_date":"2002-07-24","article_text":"1. Иностранные лица пользуются процессуальными правами и несут процессуальные обязанности наравне с российскими организациями и гражданами. Процессуальные льготы предоставляются иностранным лицам, если они предусмотрены международным договором Российской Федерации.\n\nВ случае непредставления таких доказательств арбитражный суд вправе истребовать их по своей инициативе.","article_title":"Статья 254. Процессуальные права и обязанности иностранных лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"54a55db864f33fd2f7635a860dad2b1789133363d2d6147989b906cb6cbbe701"},{"code_id":"APK_RF","article_number":"255","version_date":"2002-07-24","article_text":"1. Документы, выданные, составленные или удостоверенные по установленной форме компетентными органами иностранных государств вне пределов Российской Федерации по нормам иностранного права в отношении российских организаций и граждан или иностранных лиц, принимаются арбитражными судами в Российской Федерации при наличии легализации указанных документов или проставлении апостиля, если иное не установлено международным договором Российской Федерации.\n\n2. Документы, составленные на иностранном языке, при представлении в арбитражный суд в Российской Федерации должны сопровождаться их надлежащим образом заверенным переводом на русский язык.","article_title":"Статья 255. Требования, предъявляемые к документам иностранного происхождения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"02ac110070ec140f2e5393f78025eb6486b07a48d76863475b2d7b6956322e74"},{"code_id":"APK_RF","article_number":"256","version_date":"2002-07-24","article_text":"1. Арбитражный суд исполняет переданные ему в порядке, установленном международным договором Российской Федерации или федеральным законом, поручения иностранных судов и компетентных органов иностранных государств о выполнении отдельных процессуальных действий (вручение повесток и других документов, получение письменных доказательств, производство экспертизы, осмотр на месте и другие).\n\n2. Поручение иностранного суда или компетентного органа иностранного государства не подлежит исполнению, если:\n\n1) исполнение поручения нарушает основополагающие принципы российского права или иным образом противоречит публичному порядку Российской Федерации;\n\n2) исполнение поручения не относится к компетенции арбитражного суда в Российской Федерации;\n\n3) не установлена подлинность документа, содержащего поручение о выполнении отдельных процессуальных действий.\n\n3. Исполнение арбитражным судом поручений о выполнении отдельных процессуальных действий производится в порядке, установленном настоящим Кодексом, если иное не предусмотрено международным договором Российской Федерации.\n\n4. Арбитражные суды могут в порядке, установленном международным договором Российской Федерации или федеральным законом, обращаться к иностранным судам или компетентным органам иностранных государств с поручениями о выполнении отдельных процессуальных действий.\n\n(Дополнение главой - Федеральный закон от 29.12.2015 № 393-ФЗ)","article_title":"Статья 256. Поручения о выполнении отдельных процессуальных действий","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"decb690ad63302ee7c457d55b165b305cc8bc40a090e41afca5e8d903092dbf3"},{"code_id":"APK_RF","article_number":"256.1","version_date":"2002-07-24","article_text":"1. Предъявление в арбитражном суде иска к иностранному государству, привлечение иностранного государства к участию в деле в качестве ответчика или третьего лица, наложение ареста на имущество иностранного государства, находящееся на территории Российской Федерации, принятие в отношении этого имущества иных мер по обеспечению иска, обращение взыскания на это имущество в порядке исполнения решений арбитражного суда, а также рассмотрение заявлений о признании и принудительном исполнении решений иностранных судов в отношении имущества иностранного государства, находящегося на территории Российской Федерации, осуществляется в соответствии с Федеральным законом от 3 ноября 2015 года № 297-ФЗ \"О юрисдикционных иммунитетах иностранного государства и имущества иностранного государства в Российской Федерации\" в порядке, установленном настоящим Кодексом, если иное не предусмотрено международным договором Российской Федерации.\n\n2. Дела с участием иностранного государства рассматриваются по общим правилам искового производства с особенностями, установленными настоящей главой, главами 32 и 33 настоящего Кодекса и другими федеральными законами\n\n. Заявления о признании и принудительном исполнении решений иностранных судов в отношении имущества иностранного государства, находящегося на территории Российской Федерации, рассматриваются в порядке, установленном настоящей главой, главой 31 настоящего Кодекса и другими федеральными законами.\n\n3. Для целей настоящего Кодекса понятие \"иностранное государство\" используется в значении, определяемом Федеральным законом от 3 ноября 2015 года № 297-ФЗ \"О юрисдикционных иммунитетах иностранного государства и имущества иностранного государства в Российской Федерации\".","article_title":"Статья 256.1. Производство по делам с участием иностранного государства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"96efc922387771d212bad95e0fa8cc7d7cee41a5898fa27fe879a3c0049cde5a"},{"code_id":"APK_RF","article_number":"256.10","version_date":"2002-07-24","article_text":"1. Арбитражный суд вправе рассмотреть дело в отсутствие представителя иностранного государства, являющегося ответчиком по делу, в случае его неявки без уважительных причин в судебное заседание при соблюдении следующих условий:\n\n1) иностранное государство в соответствии с требованиями статьи 2566 настоящего Кодекса надлежащим образом извещено о принятии искового заявления к производству, о возбуждении производства по делу, а также о времени и месте судебного заседания;\n\n2) со дня вручения иностранному государству извещения о возбуждении против него дела прошло не менее шести месяцев;\n\n3) иностранным государством не заявлено ходатайство об отложении на разумный срок судебного заседания либо указанное ходатайство мотивированно отклонено судом.\n\n2. По результатам рассмотрения дела в отсутствие иностранного государства, являющегося ответчиком по делу, и при соблюдении всех условий, предусмотренных частью 1 настоящей статьи, арбитражный суд может вынести решение в отсутствие указанного иностранного государства, если установит, что в соответствии с законодательством Российской Федерации иностранное государство не пользуется судебным иммунитетом в отношении рассматриваемого спора. Копия решения арбитражного суда не позднее чем в течение пяти дней со дня его принятия направляется арбитражным судом иностранному государству в порядке, установленном статьей 256 настоящего Кодекса.\n\n3. Иностранное государство в течение двух месяцев со дня вручения ему в порядке, установленном статьей 256 настоящего Кодекса, копии указанного в части 2 настоящей статьи решения арбитражного суда вправе подать в арбитражный суд, принявший такое решение, заявление о его отмене.\n\n4. Решение арбитражного суда, вынесенное по результатам рассмотрения дела в отсутствие иностранного государства, являющегося ответчиком по делу, также может быть обжаловано сторонами в апелляционном порядке в течение месяца после истечения срока подачи ответчиком заявления об отмене этого решения арбитражного суда, а в случае, если такое заявление подано, - в течение двух месяцев со дня вынесения арбитражным судом определения об отказе в удовлетворении этого заявления.","article_title":"Статья 256.10. Рассмотрение дела в отсутствие иностранного государства, являющегося ответчиком","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"93f5190acb1a8d20dfd4f0fd4e5dd038dc12fbca90ca47e6916f26a7c3cf18cd"},{"code_id":"APK_RF","article_number":"256.11","version_date":"2002-07-24","article_text":"1. При рассмотрении арбитражным судом дела с участием иностранного государства на это иностранное государство не может быть наложен судебный штраф, а также к этому иностранному государству не могут быть предъявлены требования о предварительной оплате судебных расходов, связанных с рассмотрением дела.\n\n2. Положения части 1 настоящей статьи не препятствуют арбитражному суду взыскать с иностранного государства судебные расходы по правилам, установленным главой 9 настоящего Кодекса, при принятии арбитражным судом решения по результатам рассмотрения дела по существу.","article_title":"Статья 256.11. Привилегии и иммунитеты иностранного государства в ходе судебного разбирательства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"074ab854155a6187ec42d5577b7ba81e123bdf714d4121b84233a3b3e29376d7"},{"code_id":"APK_RF","article_number":"256.12","version_date":"2002-07-24","article_text":"Исполнение судебных актов арбитражного суда, вынесенных в отношении иностранного государства, его имущества, находящегося на территории Российской Федерации, по результатам рассмотрения соответствующих иска или заявления о признании и исполнении судебных решений другого иностранного государства, осуществляется в соответствии с законодательством Российской Федерации об исполнительном производстве. Исполнительный лист с копией судебного акта арбитражного суда направляется главному судебному приставу Российской Федерации. Одновременно арбитражный суд в порядке, установленном статьей 2566 настоящего Кодекса, извещает иностранное государство о вступлении судебного акта в законную силу и направлении исполнительных документов главному судебному приставу Российской Федерации для исполнения.\n\nРАЗДЕЛ VI. ПРОИЗВОДСТВО ПО ПЕРЕСМОТРУ СУДЕБНЫХ АКТОВ АРБИТРАЖНЫХ СУДОВ","article_title":"Статья 256.12. Порядок исполнения судебных актов арбитражного суда в отношении иностранного государства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8c179284449c81977d6a5e817707645cab975454b9b46e05b1f0190826cfc5e3"},{"code_id":"APK_RF","article_number":"256.2","version_date":"2002-07-24","article_text":"Компетенция судов Российской Федерации по рассмотрению дел с участием иностранного государства определяется по правилам, установленным главой 4 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 28.11.2018 № 451-ФЗ)","article_title":"Статья 256.2. Компетенция арбитражных судов по делам с участием иностранного государства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"311d28362c90e67be9b6ec8e99e6889a3febe3059f29cd3322236bacd6f342bc"},{"code_id":"APK_RF","article_number":"256.3","version_date":"2002-07-24","article_text":"1. Иностранное государство пользуется в отношении себя и своего имущества, находящегося на территории Российской Федерации, юрисдикционными иммунитетами с учетом положений Федерального закона от 3 ноября 2015 года № 297-ФЗ \"О юрисдикционных иммунитетах иностранного государства и имущества иностранного государства в Российской Федерации\".\n\n2. Иностранное государство пользуется процессуальными правами и выполняет процессуальные обязанности наравне с российскими гражданами и организациями, в том числе правом вести свои дела в суде через представителей. Полномочия представителя иностранного государства должны быть выражены в доверенности или ином соответствующем документе, выданном представляемым иностранным государством и оформленном в соответствии с законодательством Российской Федерации или законодательством иностранного государства, с учетом требований, предусмотренных статьей 255 настоящего Кодекса.\n\n3. Представитель иностранного государства вправе совершать от имени представляемого им иностранного государства все процессуальные действия, за исключением действий, указанных в части 4 настоящей статьи, если иное не предусмотрено в доверенности или ином соответствующем документе, выданном представляемым иностранным государством.\n\n4. В доверенности или ином соответствующем документе, выданном представляемым иностранным государством, должно быть специально оговорено право представителя этого иностранного государства на подписание отзыва на исковое заявление, признание иска, отказа от судебного иммунитета, иммунитета в отношении мер по обеспечению иска, иммунитета в отношении исполнения судебного решения, предъявление встречного иска, изменение основания или предмета встречного иска, заключение мирового соглашения и соглашения по фактическим обстоятельствам, передачу своих полномочий представителя другому лицу (передоверие), получение судебных извещений (включая копии судебных актов), обжалование судебных актов, подписание, подачу заявления о пересмотре судебных актов по новым или вновь открывшимся обстоятельствам, а также на получение присужденных денежных средств или иного имущества.","article_title":"Статья 256.3. Юрисдикционные иммунитеты, процессуальные права и обязанности иностранного государства, представительство","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"24ad692e4146097559688831051c6c184464eee7e846f06cdae6280810c8a2b4"},{"code_id":"APK_RF","article_number":"256.4","version_date":"2002-07-24","article_text":"1. Исковое заявление по спору с иностранным государством и прилагаемые к нему документы должны соответствовать требованиям статей 125 и 126 настоящего Кодекса и подаются в арбитражный суд с копиями искового заявления и прилагаемых к нему документов в соответствии с количеством ответчиков и третьих лиц.\n\n2. К исковому заявлению также прилагается надлежащим образом заверенный перевод искового заявления и прилагаемых к нему документов на официальный язык или один из официальных языков иностранного государства, привлекаемого к участию в деле.","article_title":"Статья 256.4. Подача искового заявления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6ea5a9ad1e792ce664b6f071a00bb2b47ad1af09ba5f792554128842e7a1621e"},{"code_id":"APK_RF","article_number":"256.5","version_date":"2002-07-24","article_text":"1. Меры по обеспечению иска применяются арбитражным судом по заявлению лиц, участвующих в деле, в порядке, установленном главой 8 настоящего Кодекса, за исключением случаев, если иностранное государство и его имущество, находящееся на территории Российской Федерации, пользуются иммунитетом в отношении мер по обеспечению иска и иностранное государство не отказалось от этого иммунитета.\n\n2. Примененные арбитражным судом меры по обеспечению иска подлежат отмене, если в ходе судебного разбирательства будет установлено, что иностранное государство и его имущество, находящееся на территории Российской Федерации, пользуются иммунитетом в отношении мер по обеспечению иска или иммунитетом в отношении исполнения судебного решения и иностранное государство не отказалось от этих иммунитетов.","article_title":"Статья 256.5. Особенности применения мер по обеспечению иска","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bece0210f1fc999f16fcb3ce664b9f273496ec542abdbdc70d7b6a9b5b75ba22"},{"code_id":"APK_RF","article_number":"256.6","version_date":"2002-07-24","article_text":"1. Направление иностранному государству судебного извещения о возбуждении против него дела в суде Российской Федерации, а также иного процессуального документа, подлежащего вручению иностранному государству (далее - судебное извещение), осуществляется арбитражным судом в соответствии с применимым международным договором Российской Федерации.\n\n2. В случае отсутствия применимого международного договора Российской Федерации арбитражный суд направляет судебное извещение в федеральный орган исполнительной власти, уполномоченный в области юстиции, для последующего направления (вручения) иностранному государству по дипломатическим каналам через федеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере международных отношений Российской Федерации.\n\n3. Заверенная копия дипломатической ноты, препровождающей направление судебного извещения иностранному государству, с указанием даты ее получения компетентным органом иностранного государства, ведающим вопросами иностранных дел, направляется в арбитражный суд, направивший извещение. Дата получения указанной дипломатической ноты компетентным органом иностранного государства, ведающим вопросами иностранных дел, считается датой вручения судебного извещения.\n\n4. Поступившие в Российскую Федерацию от иностранного государства по дипломатическим каналам отзыв, заявление, ходатайство и иные документы, касающиеся предъявленного к этому иностранному государству иска, направляются федеральным органом исполнительной власти, уполномоченным в области юстиции, в арбитражный суд, в производстве которого находится дело по иску к указанному иностранному государству.\n\n5. Указанные в частях 1 - 3 настоящей статьи судебные извещения могут быть вручены арбитражным судом непосредственно под расписку представителю иностранного государства, если он участвует в деле и в установленном порядке наделен соответствующими полномочиями.\n\n6. Судебные извещения о назначении предварительного судебного заседания или о назначении дела к разбирательству в судебном заседании направляются иностранному государству в порядке, установленном настоящей статьей, не позднее чем за шесть месяцев до дня судебного заседания.\n\n7. Судебные извещения, подлежащие вручению иностранному государству, составляются в двух экземплярах, заверяются судом и сопровождаются надлежащим образом заверенным переводом на официальный язык или один из официальных языков иностранного государства, привлекаемого к участию в деле.","article_title":"Статья 256.6. Направление и вручение иностранному государству извещений и иных процессуальных документов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"22695dd3199d5b3924d3168155f7717611540920fcfaef17a34c433be98cf1af"},{"code_id":"APK_RF","article_number":"256.7","version_date":"2002-07-24","article_text":"1. В предварительном судебном заседании, проводимом в соответствии со статьей 136 настоящего Кодекса, арбитражный суд с участием сторон также решает вопрос о наличии у иностранного государства судебного иммунитета в отношении рассматриваемого спора.\n\n2. В случае неявки надлежащим образом извещенного о дате, времени и месте предварительного судебного заседания представителя иностранного государства суд принимает решение на основе материалов, имеющихся в деле.\n\n3. Если имеющиеся в деле материалы не позволяют арбитражному суду в предварительном судебном заседании сделать вывод о наличии у иностранного государства судебного иммунитета в отношении рассматриваемого спора, этот вопрос подлежит разрешению при разбирательстве в судебном заседании при рассмотрении дела.\n\n4. Установленные арбитражным судом обстоятельства и вывод арбитражного суда о наличии или отсутствии у иностранного государства судебного иммунитета, иммунитета в отношении мер по обеспечению иска и иммунитета в отношении исполнения решения суда должны быть отражены в судебном акте, принимаемом по результатам рассмотрения дела.\n\n5. В случае, если суд в предварительном судебном заседании или при разбирательстве в судебном заседании пришел к выводу о наличии у иностранного государства судебного иммунитета, суд прекращает производство по делу в отношении его.","article_title":"Статья 256.7. Особенности предварительного судебного заседания и прекращения производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"16c94f03b893b1bceeb3abbb29482a0ae4bebbd5fb6aa7439c6fa8f989188423"},{"code_id":"APK_RF","article_number":"256.8","version_date":"2002-07-24","article_text":"1. Федеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере международных отношений Российской Федерации, по инициативе суда или по собственной инициативе может участвовать в деле для дачи заключения по вопросам предоставления юрисдикционных иммунитетов Российской Федерации и ее имуществу в иностранном государстве.\n\n2. Заключение указанного в части 1 настоящей статьи федерального органа исполнительной власти может быть получено по вопросам о статусе образования, органа, организации, должностного лица, привлекаемых к участию в деле в качестве иностранного государства, о наличии судебного иммунитета в отношении рассматриваемого спора, иммунитета имущества иностранного государства, находящегося на территории Российской Федерации и являющегося предметом спора, иммунитета в отношении мер по обеспечению иска и иммунитета в отношении исполнения решения суда, о юрисдикционных иммунитетах, предоставляемых Российской Федерации в иностранном государстве, и их объеме, а также по иным вопросам, относящимся к компетенции указанного государственного органа.\n\n3. Заключение указанного в части 1 настоящей статьи федерального органа исполнительной власти подлежит оценке судом по установленным настоящим Кодексом правилам оценки доказательств.","article_title":"Статья 256.8. Участие в деле государственных органов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ddd185007ed5d8d8be6b191260440e48105a3c036217e216f51b29b44f4fb53c"},{"code_id":"APK_RF","article_number":"256.9","version_date":"2002-07-24","article_text":"1. При рассмотрении иска арбитражный суд по собственной инициативе или по ходатайству стороны в соответствии с Федеральным законом от 3 ноября 2015 года № 297-ФЗ \"О юрисдикционных иммунитетах иностранного государства и имущества иностранного государства в Российской Федерации\" может применить принцип взаимности, если в ходе судебного разбирательства будет установлено, что объем юрисдикционных иммунитетов, предоставляемых Российской Федерации в иностранном государстве, не соответствует объему юрисдикционных иммунитетов, предоставляемых этому иностранному государству в соответствии с законодательством Российской Федерации при разрешении конкретного спора.\n\n2. Соотношение объема юрисдикционных иммунитетов, предоставляемых Российской Федерации в иностранном государстве, и юрисдикционных иммунитетов иностранного государства в Российской Федерации определяется арбитражным судом на основании доказательств, представленных сторонами, и заключений государственных органов.\n\n3. Мотивированное решение арбитражного суда о применении принципа взаимности и в соответствии с ним ограничении юрисдикционных иммунитетов иностранного государства при рассмотрении конкретного дела указывается в решении арбитражного суда, принимаемом по итогам рассмотрения этого дела.","article_title":"Статья 256.9. Применение принципа взаимности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"866a3983605c7cef57cb02c183bd30dc95263e6457e0276e79bdb6ab49106347"},{"code_id":"APK_RF","article_number":"257","version_date":"2002-07-24","article_text":"1. Лица, участвующие в деле, а также иные лица в случаях, предусмотренных настоящим Кодексом, вправе обжаловать в порядке апелляционного производства решение арбитражного суда первой инстанции, не вступившее в законную силу.","article_title":"Статья 257. Право апелляционного обжалования","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"77de8803ff56fd30fced12be2b30f9901406bb28e472c1f69eede4a623ae6eb0"},{"code_id":"APK_RF","article_number":"258","version_date":"2002-07-24","article_text":"Апелляционные жалобы рассматривает в порядке апелляционного производства арбитражный суд апелляционной инстанции, образованный в соответствии с Федеральным конституционным законом \"Об арбитражных судах в Российской Федерации\".","article_title":"Статья 258. Арбитражный суд апелляционной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"17969d1308607b0181b28a9471b035d901c7f7cadaa1dffc01f18e9f1be24cc4"},{"code_id":"APK_RF","article_number":"259","version_date":"2002-07-24","article_text":"1. Апелляционная жалоба может быть подана в течение месяца после принятия арбитражным судом первой инстанции обжалуемого решения, если иной срок не установлен настоящим Кодексом.","article_title":"Статья 259. Срок подачи апелляционной жалобы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c58567a0bdec3495f012993b814187288dd4fd61ca81d6275ccebb2ad13d21f7"},{"code_id":"APK_RF","article_number":"26","version_date":"2002-07-24","article_text":"1. Судья, заявивший самоотвод, а также судья, в отношении которого удовлетворено заявление об отводе, заменяется другим судьей.\n\n2. В случае удовлетворения заявления о самоотводе или об отводе судьи, либо нескольких судей, либо всего состава суда дело рассматривается в том же арбитражном суде, но в ином составе судей.\n\n3. Если в результате удовлетворения самоотводов и отводов невозможно сформировать новый состав суда для рассмотрения данного дела в том же арбитражном суде, дело передается в другой арбитражный суд того же уровня в порядке, установленном статьей 39 настоящего Кодекса.\n\n(Обозначение и наименование параграфа исключены - Федеральный закон от 28.11.2018 № 451-ФЗ)","article_title":"Статья 26. Последствия удовлетворения заявления об отводе","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cc084e56f4067ab0bdfe791e2548eafce2d2b8070527486b3ef9258f76ede208"}]$law7d0013$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
